                          class="ppo-badge ppo-badge--err ml-1"
                        >
                          <v-icon left size="10" color="#dc2626"
                            >mdi-alert-circle</v-icon
                          >
                          Needs KPI
                        </v-chip>
                        <template v-if="canEdit">
                          <v-tooltip bottom>
                            <template v-slot:activator="{ on }">
                              <v-btn
                                v-on="on"
                                icon
                                x-small
                                class="ppo-micro ml-1"
                                @click="$emit('edit-sub', sub)"
                              >
                                <v-icon size="11">mdi-pencil</v-icon>
                              </v-btn> </template
                            ><span>Edit sub-activity</span>
                          </v-tooltip>
                          <v-tooltip bottom>
                            <template v-slot:activator="{ on }">
                              <v-btn
                                v-on="on"
                                icon
                                x-small
                                class="ppo-micro ppo-micro--red"
                                @click="$emit('delete-sub', sub)"
                              >
                                <v-icon size="11">mdi-trash-can-outline</v-icon>
                              </v-btn> </template
                            ><span>Delete sub-activity</span>
                          </v-tooltip>
                          <v-btn
                            x-small
                            class="ppo-micro-btn ppo-micro-btn--indigo"
                            @click="$emit('add-kpi', sub)"
                          >
                            <v-icon left size="11">mdi-chart-bar</v-icon>KPI
                          </v-btn>
                        </template>
                      </div>
                    </div>
                    <div
                      v-for="(sub, subIdx) in getSubActivities(activity.id)"
                      :key="'kpis-' + sub.id"
                    >
                      <div
                        v-if="getKpis(sub.id).length > 0"
                        class="ppo-kpis-group"
                      >
                        <div class="ppo-kpis-group__header">
                          <v-icon size="12" color="#6366f1"
                            >mdi-subdirectory-arrow-right</v-icon
                          >
                          <span
                            >KPIs for {{ objIndex + 1 }}.{{ actIndex + 1 }}.{{
                              subIdx + 1
                            }}: {{ sub.name }}</span
                          >
                        </div>
                        <div class="ppo-kpis-list">
                          <div
                            v-for="kpi in getKpis(sub.id)"
                            :key="kpi.id"
                            class="ppo-kpi-row ppo-kpi-row--sub"
                            :class="{
                              'ppo-kpi-row--error': _errorKpiIds.has(kpi.id),
                            }"
                          >
                            <div class="ppo-kpi-row__info">
                              <v-icon size="12" color="#6366f1"
                                >mdi-chart-bar</v-icon
                              >
                              <span class="ppo-kpi-row__name">{{
                                kpi.name
                              }}</span>
                              <template v-if="canEdit">
                                <v-tooltip bottom>
                                  <template v-slot:activator="{ on }">
                                    <v-btn
                                      v-on="on"
                                      icon
                                      x-small
                                      class="ppo-micro ml-1"
                                      @click="$emit('edit-kpi', kpi)"
                                    >
                                      <v-icon size="11">mdi-pencil</v-icon>
                                    </v-btn> </template
                                  ><span>Edit KPI</span>
                                </v-tooltip>
                                <v-tooltip bottom>
                                  <template v-slot:activator="{ on }">
                                    <v-btn
                                      v-on="on"
                                      icon
                                      x-small
                                      class="ppo-micro ppo-micro--red"
                                      @click="$emit('delete-kpi', kpi)"
                                    >
                                      <v-icon size="11"
                                        >mdi-trash-can-outline</v-icon
                                      >
                                    </v-btn> </template
                                  ><span>Delete KPI</span>
                                </v-tooltip>
                              </template>
                            </div>
                            <div class="ppo-kpi-row__target">
                              <template v-if="getTargetForKpi(kpi.id)">
                                <v-chip
                                  x-small
                                  class="ppo-target-chip ppo-target-chip--amber"
                                >
                                  <v-icon left size="11" color="#d97706"
                                    >mdi-check-circle</v-icon
                                  >
                                  {{ getTargetForKpi(kpi.id).name }}
                                  <template v-if="canEdit">
                                    <v-btn
                                      icon
                                      x-small
                                      class="ppo-chip-btn ml-1"
                                      @click="
                                        $emit(
                                          'edit-target',
                                          getTargetForKpi(kpi.id),
                                        )
                                      "
                                    >
                                      <v-icon size="10" color="#d97706"
                                        >mdi-pencil</v-icon
                                      >
                                    </v-btn>
                                    <v-btn
                                      icon
                                      x-small
                                      class="ppo-chip-btn"
                                      @click="
                                        $emit(
                                          'delete-target',
                                          getTargetForKpi(kpi.id),
                                        )
                                      "
                                    >
                                      <v-icon size="10" color="#ef4444"
                                        >mdi-trash-can-outline</v-icon
                                      >
                                    </v-btn>
                                  </template>
                                </v-chip>
                              </template>
                              <template v-else>
                                <span class="ppo-no-target">
                                  <v-icon
                                    size="11"
                                    :color="canEdit ? '#dc2626' : '#94a3b8'"
                                  >
                                    {{
                                      canEdit
                                        ? "mdi-alert-circle"
                                        : "mdi-minus-circle-outline"
                                    }}
                                  </v-icon>
                                  No target
                                </span>
                                <v-btn
                                  v-if="canEdit"
                                  x-small
                                  class="ppo-micro-btn ppo-micro-btn--emerald ml-1"
                                  @click="$emit('add-target', kpi)"
                                >
                                  <v-icon left size="11">mdi-plus</v-icon>Add
                                  Target
                                </v-btn>
                              </template>
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </v-card-text>
          </v-expand-transition>

          <div
            v-if="!expanded[objIndex]"
            class="ppo-card__footer"
            :class="`ppo-card__footer--${accentColor}`"
            @click="toggle(objIndex)"
          >
            <span>
              {{ getActivities(objective.id).length }} activities ·
              {{ countKpis(objective.id) }} KPIs ·
              {{ countTargets(objective.id) }} targets
            </span>
            <v-icon
              size="14"
              :color="accentColor === 'teal' ? '#0d9488' : '#f97316'"
            >
              mdi-chevron-down
            </v-icon>
          </div>
        </v-card>
      </div>
      <!-- /right column -->
    </div>
  </div>
</template>

<script>
export default {
  name: "PerformancePlanObjectives",

  props: {
    planId: { type: String, default: null }, // FHIR ID of the plan
    canEdit: { type: Boolean, default: false },
    accentColor: { type: String, default: "orange" }, // 'orange' | 'teal'
  },

  data() {
    return {
      loading: false,
      objectives: [],
      activities: [],
      subActivities: [],
      kpis: [],
      targets: [],
      supervisorTargetsByObjective: {},
      expanded: {},
    };
  },

  watch: {
    planId: {
      immediate: true,
      async handler(id) {
        if (id) {
          await this.reload();
        } else {
          this.objectives = [];
          this.activities = [];
          this.subActivities = [];
          this.kpis = [];
          this.targets = [];
          this.supervisorTargetsByObjective = {};
          this.expanded = {};
          this._emitDataLoaded();
        }
      },
    },
  },

  computed: {
    leftObjectives() {
      return this.objectives
        .map((objective, objIndex) => ({ objective, objIndex }))
        .filter((_, i) => i % 2 === 0);
    },
    rightObjectives() {
      return this.objectives
        .map((objective, objIndex) => ({ objective, objIndex }))
        .filter((_, i) => i % 2 === 1);
    },

    objectiveCompleteness() {
      return this.objectives.map((obj) => {
        const errors = [];
        const activities = this.getActivities(obj.id);
        if (activities.length === 0) {
          errors.push({
            level: "objective",
            id: obj.id,
            message: "At least one activity is required",
          });
        }
        for (const act of activities) {
          const subs = this.getSubActivities(act.id);
          if (subs.length === 0) {
            const kpis = this.getKpis(act.id);
            if (kpis.length === 0) {
              errors.push({
                level: "activity",
                id: act.id,
                message: `"${act.name}": needs at least one KPI`,
              });
            }
            for (const kpi of kpis) {
              if (!this.getTargetForKpi(kpi.id)) {
                errors.push({
                  level: "kpi",
                  id: kpi.id,
                  activityId: act.id,
                  message: `"${act.name}" › KPI "${kpi.name}": missing target`,
                });
              }
            }
          } else {
            for (const sub of subs) {
              const kpis = this.getKpis(sub.id);
              if (kpis.length === 0) {
                errors.push({
                  level: "subactivity",
                  id: sub.id,
                  activityId: act.id,
                  message: `"${act.name}" › "${sub.name}": needs at least one KPI`,
                });
              }
              for (const kpi of kpis) {
                if (!this.getTargetForKpi(kpi.id)) {
                  errors.push({
                    level: "kpi",
                    id: kpi.id,
                    activityId: act.id,
                    subId: sub.id,
                    message: `"${act.name}" › "${sub.name}" › KPI "${kpi.name}": missing target`,
                  });
                }
              }
            }
            for (const kpi of this.getKpis(act.id)) {
              if (!this.getTargetForKpi(kpi.id)) {
                errors.push({
                  level: "kpi",
                  id: kpi.id,
                  activityId: act.id,
                  message: `"${act.name}" › KPI "${kpi.name}": missing target`,
                });
              }
            }
          }
        }
        return { objective: obj, errors, isComplete: errors.length === 0 };
      });
    },

    allPlanErrors() {
      return this.objectiveCompleteness.flatMap((o) => o.errors);
    },

    _errorActivityIds() {
      const s = new Set();
      this.allPlanErrors.forEach((e) => {
        if (e.activityId) s.add(e.activityId);
        if (e.level === "activity") s.add(e.id);
      });
      return s;
    },
    _errorSubIds() {
      const s = new Set();
      this.allPlanErrors.forEach((e) => {
        if (e.level === "subactivity") s.add(e.id);
      });
      return s;
    },
    _errorKpiIds() {
      const s = new Set();
      this.allPlanErrors.forEach((e) => {
        if (e.level === "kpi") s.add(e.id);
      });
      return s;
    },
  },

  methods: {
    // ── Public reload API (called by parent via $refs) ─────────────────────
    async reload() {
      this.loading = true;
      try {
        await this._loadObjectives();
        await this._loadActivities();
        await this._loadSubActivities();
        await this._loadKpis();
        await this._loadTargets();
        this._emitDataLoaded();
      } finally {
        this.loading = false;
      }
    },

    async reloadObjectives() {
      await this._loadObjectives();
      await this._loadActivities();
      await this._loadSubActivities();
      await this._loadKpis();
      await this._loadTargets();
      this._emitDataLoaded();
    },

    async reloadActivities() {
      await this._loadActivities();
      await this._loadSubActivities();
      await this._loadKpis();
      await this._loadTargets();
      this._emitDataLoaded();
    },

    async reloadSubActivities() {
      await this._loadSubActivities();
      await this._loadKpis();
      await this._loadTargets();
      this._emitDataLoaded();
    },

    async reloadKpis() {
      await this._loadKpis();
      await this._loadTargets();
      this._emitDataLoaded();
    },

    async reloadTargets() {
      await this._loadTargets();
      this._emitDataLoaded();
    },

    // ── Private FHIR loaders ─────────────────────────────────────────────
    async _loadObjectives() {
      if (!this.planId) return;
      try {
        const params = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/performance-objective-profile",
          performanceplan: `Basic/${this.planId}`,
        });
        const r = await fetch(`/fhir/Basic?${params}`);
        const b = await r.json();
        this.objectives = b.entry
          ? b.entry.map((e) => this._extractObjectiveData(e.resource))
          : [];
        // Reset and open first card
        const next = {};
        if (this.objectives.length > 0) next[0] = true;
        this.expanded = next;
        // Load supervisor targets
        this.supervisorTargetsByObjective = {};
        for (const obj of this.objectives) {
          if (obj.parentActivityId) {
            await this._loadSupervisorActivityDetails(
              obj.id,
              obj.parentActivityId,
            );
          }
        }
      } catch (e) {
        console.error("Error loading objectives:", e);
      }
    },

    async _loadActivities() {
      if (!this.objectives.length) {
        this.activities = [];
        return;
      }
      try {
        const params = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/performance-activity-profile",
          parent: this.objectives.map((o) => o.id).join(","),
        });
        const r = await fetch(`/fhir/Basic?${params}`);
        const b = await r.json();
        this.activities = b.entry
          ? b.entry.map((e) => this._extractActivityData(e.resource))
          : [];
      } catch (e) {
        console.error("Error loading activities:", e);
      }
    },

    async _loadSubActivities() {
      if (!this.activities.length) {
        this.subActivities = [];
        return;
      }
      try {
        const params = new URLSearchParams({
          _profile:
            "http://ihris.org/fhir/StructureDefinition/performance-subactivity-profile",
          parent: this.activities.map((a) => a.id).join(","),
        });
        const r = await fetch(`/fhir/Basic?${params}`);
        const b = await r.json();
        this.subActivities = b.entry
          ? b.entry.map((e) => this._extractSubActivityData(e.resource))
          : [];
      } catch (e) {
        console.error("Error loading sub-activities:", e);
      }
    },

    async _loadKpis() {
      if (!this.activities.length && !this.subActivities.length) {
        this.kpis = [];
        return;
      }
      try {
        const ids = [
          ...this.activities.map((a) => a.id),
          ...this.subActivities.map((s) => s.id),
        ].join(",");
        const params = new URLSearchParams();
        params.append(
          "_profile",
          "http://ihris.org/fhir/StructureDefinition/performance-kpi-profile",
        );
        params.append("parent", ids);
        const r = await fetch(`/fhir/Basic?${params}`);
        const b = await r.json();
        this.kpis = b.entry
          ? b.entry.map((e) => this._extractKpiData(e.resource))
          : [];
      } catch (e) {
        console.error("Error loading KPIs:", e);
      }
    },

    async _loadTargets() {
      if (!this.kpis.length) {
        this.targets = [];
        return;
      }
      try {
        const params = new URLSearchParams();
        params.append(
          "_profile",
          "http://ihris.org/fhir/StructureDefinition/performance-target-profile",
        );
        params.append("parent", this.kpis.map((k) => k.id).join(","));
        const r = await fetch(`/fhir/Basic?${params}`);
        const b = await r.json();
        this.targets = b.entry
          ? b.entry.map((e) => this._extractTargetData(e.resource))
          : [];
      } catch (e) {
        console.error("Error loading targets:", e);
      }
    },

    async _loadSupervisorActivityDetails(objectiveId, activityId) {
      try {
        const r = await fetch(`/fhir/Basic/${activityId}`);
        const activity = await r.json();
        const isSubActivity = activity.meta?.profile?.[0]?.includes(
          "performance-subactivity-profile",
        );
        this.$set(this.supervisorTargetsByObjective, objectiveId, {
          id: activity.id,
          name: this._ext(activity, "ihris-basic-name")?.valueString || "",
          description: this._ext(activity, "description")?.valueString || "",
          type: isSubActivity ? "sub-activity" : "activity",
        });
      } catch (e) {
        console.error("Error loading supervisor activity:", e);
      }
    },

    // ── Data emit ────────────────────────────────────────────────────────
    _emitDataLoaded() {
      this.$emit("data-loaded", {
        objectives: this.objectives,
        activities: this.activities,
        subActivities: this.subActivities,
        kpis: this.kpis,
        targets: this.targets,
        supervisorTargetsByObjective: this.supervisorTargetsByObjective,
        objectiveCompleteness: this.objectiveCompleteness,
        allPlanErrors: this.allPlanErrors,
      });
    },

    // ── Extractors ───────────────────────────────────────────────────────
    _ext(resource, url) {
      return resource.extension?.find((e) => e.url.includes(url));
    },
    _extractObjectiveData(r) {
      return {
        id: r.id,
        name: this._ext(r, "ihris-basic-name")?.valueString || "",
        description: this._ext(r, "description")?.valueString || "",
        performancePlanId:
          this._ext(
            r,
            "performance-plan-reference",
          )?.valueReference?.reference?.split("/")[1] || null,
        // Try the new extension key first; fall back to the old one for records
        // saved before the activity-reference change was applied on the backend.
        parentActivityId:
          (
            this._ext(r, "objective-activity-reference") ||
            this._ext(r, "objective-target-reference")
          )?.valueReference?.reference?.split("/")[1] || null,
      };
    },
    _extractActivityData(r) {
      return {
        id: r.id,
        name: this._ext(r, "ihris-basic-name")?.valueString || "",
        description: this._ext(r, "description")?.valueString || "",
        parentId:
          this._ext(r, "parent")?.valueReference?.reference?.split("/")[1] ||
          null,
      };
    },
    _extractSubActivityData(r) {
      return {
        id: r.id,
        name: this._ext(r, "ihris-basic-name")?.valueString || "",
        description: this._ext(r, "description")?.valueString || "",
        parentId:
          this._ext(r, "parent")?.valueReference?.reference?.split("/")[1] ||
          null,
      };
    },
    _extractKpiData(r) {
      return {
        id: r.id,
        name: this._ext(r, "ihris-basic-name")?.valueString || "",
        description: this._ext(r, "description")?.valueString || "",
        parentId:
          this._ext(r, "parent")?.valueReference?.reference?.split("/")[1] ||
          null,
      };
    },
    _extractTargetData(r) {
      return {
        id: r.id,
        name: this._ext(r, "ihris-basic-name")?.valueString || "",
        description: this._ext(r, "description")?.valueString || "",
        parentId:
          this._ext(r, "parent")?.valueReference?.reference?.split("/")[1] ||
          null,
      };
    },

    // ── Template helpers ─────────────────────────────────────────────────
    toggle(index) {
      this.$set(this.expanded, index, !this.expanded[index]);
    },
    getActivities(objId) {
      return this.activities.filter((a) => a.parentId === objId);
    },
    getSubActivities(actId) {
      return this.subActivities.filter((s) => s.parentId === actId);
    },
    getKpis(parentId) {
      return this.kpis.filter((k) => k.parentId === parentId);
    },
    getTargetForKpi(kpiId) {
      return this.targets.find((t) => t.parentId === kpiId) || null;
    },
    getSupervisorTarget(objectiveId) {
      return this.supervisorTargetsByObjective[objectiveId] || null;
    },
    countKpis(objId) {
      let n = 0;
      for (const act of this.getActivities(objId)) {
        n += this.getKpis(act.id).length;
        for (const sub of this.getSubActivities(act.id))
          n += this.getKpis(sub.id).length;
      }
      return n;
    },
    countTargets(objId) {
      let n = 0;
      for (const act of this.getActivities(objId)) {
        for (const kpi of this.getKpis(act.id)) {
          if (this.getTargetForKpi(kpi.id)) n++;
        }
        for (const sub of this.getSubActivities(act.id)) {
          for (const kpi of this.getKpis(sub.id)) {
            if (this.getTargetForKpi(kpi.id)) n++;
          }
        }
      }
      return n;
    },
    headerBg(index) {
      const bgs = [
        "linear-gradient(135deg, #1e3a5f 0%, #1e40af 100%)",
        "linear-gradient(135deg, #0f4c5c 0%, #0e7490 100%)",
        "linear-gradient(135deg, #14532d 0%, #166534 100%)",
        "linear-gradient(135deg, #3b0764 0%, #6d28d9 100%)",
        "linear-gradient(135deg, #7c2d12 0%, #9a3412 100%)",
        "linear-gradient(135deg, #7f1d1d 0%, #991b1b 100%)",
      ];
      return bgs[index % bgs.length];
    },
  },
};
